-- 대기 중인 것과 그 원인 (PostgreSQL)
SELECT pid, wait_event_type, wait_event, state,
       now() - query_start AS 경과, left(query, 80)
  FROM pg_stat_activity
 WHERE state <> 'idle' ORDER BY 경과 DESC;

-- 누가 누구를 막는지
SELECT pg_blocking_pids(pid), pid, left(query,60) FROM pg_stat_activity
 WHERE cardinality(pg_blocking_pids(pid)) > 0;

